Chương trình sau đây thực hiện điều gì?
unsigned int mystery(unsigned int a, unsigned int b);
int main(void) { ... scanf("%u%u", &x, &y); printf("The result is %u\n", mystery(x, y)); }
unsigned int mystery(unsigned int a, unsigned int b) {
   if (1 == b) { return a; }
   else { return a + mystery(a, b - 1); }
}

