#include <iostream>
#include <string>

unsigned int recursiveGCD(unsigned int a, unsigned int b, int depth = 0) {
    std::string indent(depth * 2, ' ');
    std::cout << indent << "gcd(" << a << ", " << b << ")\n";
    if (b == 0) {
        return a;
    }
    return recursiveGCD(b, a % b, depth + 1);
}

void solveHanoi(int n, int src, int dest, int temp) {
    if (n == 1) {
        std::cout << src << " -> " << dest << "\n";
        return;
    }
    solveHanoi(n - 1, src, temp, dest);
    std::cout << src << " -> " << dest << "\n";
    solveHanoi(n - 1, temp, dest, src);
}

int main() {
    int hanoiDisks = 0;
    unsigned int x = 0, y = 0;
    if (std::cin >> hanoiDisks >> x >> y) {
        std::cout << "Hanoi Moves:" << "\n";
        solveHanoi(hanoiDisks, 1, 3, 2);
        std::cout << "GCD Trace:" << "\n";
        unsigned int g = recursiveGCD(x, y);
        std::cout << "Result: " << g << "\n";
    }
    return 0;
}

#include <iostream>

// Tail-recursive Fibonacci with accumulators
long long fibTail(int n, long long a = 0, long long b = 1) {
    if (n == 0) return a;
    if (n == 1) return b;
    return fibTail(n - 1, b, a + b);
}

// Corrected sum function (fixing Exercise 5.46e)
int sum(int n) {
    if (0 == n) {
        return 0;
    }
    return n + sum(n - 1);
}

int main() {
    int n = 0;
    if (std::cin >> n) {
        std::cout << "Sum(1.." << n << ") = " << sum(n) << "\n";
        std::cout << "Fib(" << n << ") = " << fibTail(n) << "\n";
    }
    return 0;
}
